challenge_result.investigation_instruction:
{
  "plans": [
    {
      "hypothesis_id": "h1",
      "hypothesis_statement": "rtpengine is the source of the severe media packet loss observed in the 'derived.rtpengine_loss_ratio' metric.",
      "primary_suspect_nf": "rtpengine",
      "probes": [
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Returns rate-based MOS/loss/jitter alongside RTPEngine errors.",
          "expected_if_hypothesis_holds": "Probe reads a non-zero value for `rtpengine.errors_per_second`, indicating active relay-loop errors.",
          "falsifying_observation": "Probe reads that `rtpengine.errors_per_second` is zero, suggesting the relay loop is healthy and packet loss originates elsewhere in the media path.",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "window_seconds=120 to confirm MOS drop and packet-loss percentage across the same window",
          "expected_if_hypothesis_holds": "A high value for `rtpengine.loss_ratio` is observed, confirming sustained packet loss.",
          "falsifying_observation": "The `rtpengine.loss_ratio` is within its healthy baseline (0.0-0.1), which would contradict the initial anomaly detection.",
          "conflates_with": []
        },
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Check UPF's downlink packet rate (traffic from rtpengine).",
          "expected_if_hypothesis_holds": "UPF's per-UE downlink packet rate (`gtp_outdatapktn3upf_per_ue`) is significantly reduced or zero, suggesting that packets are being dropped by rtpengine before reaching the UPF.",
          "falsifying_observation": "UPF's per-UE downlink packet rate (`gtp_outdatapktn3upf_per_ue`) is at a healthy, non-zero level, indicating that rtpengine is forwarding packets correctly to the UPF.",
          "conflates_with": []
        }
      ],
      "notes": "This plan uses the KB-authored probe candidates for h1. It first checks for errors within rtpengine, then confirms the high-level loss metric, and finally checks a downstream component (UPF) to see if packets are being forwarded from rtpengine. This avoids compositional ambiguity. Reference 'vonr_media' flow, steps 3 and 4."
    },
    {
      "hypothesis_id": "h2",
      "hypothesis_statement": "upf is the source of the data plane fault, causing the collapse in activity reported by the `core.upf.activity_during_calls_collapsed` event and contributing to the packet loss seen by rtpengine.",
      "primary_suspect_nf": "upf",
      "probes": [
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Returns UPF in/out pps, RTPEngine sessions; correlate.",
          "expected_if_hypothesis_holds": "The `upf.activity_during_calls` metric is near zero, confirming that media traffic is not flowing through the UPF as expected during active calls.",
          "falsifying_observation": "The `upf.activity_during_calls` metric is close to its healthy value of 1.0, indicating media is flowing correctly through the UPF.",
          "conflates_with": []
        },
        {
          "tool": "measure_rtt",
          "args_hint": "Probe path from rtpengine to upf's N6 interface IP.",
          "expected_if_hypothesis_holds": "High RTT or packet loss is observed.",
          "falsifying_observation": "Low RTT and zero packet loss are observed.",
          "conflates_with": [
            "the network path between rtpengine and upf"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "Probe path from smf to upf's N4 interface IP.",
          "expected_if_hypothesis_holds": "High RTT or packet loss is observed. If the rtpengine->upf probe also shows loss, it strengthens the hypothesis that the UPF is the source.",
          "falsifying_observation": "Low RTT and zero packet loss are observed. If the rtpengine->upf probe showed loss but this one does not, it suggests the fault lies on the path to the N6 interface, not the UPF itself.",
          "conflates_with": []
        }
      ],
      "notes": "This plan confirms the collapsed activity at the UPF. It then uses a pair of `measure_rtt` probes from different sources (rtpengine, smf) to the suspect NF (upf) to disambiguate between a fault in the UPF itself versus a fault on one of the network paths leading to it. This directly addresses the feedback on compositional probes. Reference 'data_pdu_session_user_traffic' and 'vonr_media' flows."
    },
    {
      "hypothesis_id": "h3",
      "hypothesis_statement": "The HSS is the source of the IMS signaling disruption, evidenced by anomalous Diameter reply rates from both I-CSCF and S-CSCF.",
      "primary_suspect_nf": "pyhss",
      "probes": [
        {
          "tool": "measure_rtt",
          "args_hint": "from='icscf', to_ip='<pyhss_ip>'",
          "expected_if_hypothesis_holds": "High RTT or packet loss is observed.",
          "falsifying_observation": "Low RTT and zero packet loss are observed.",
          "conflates_with": [
            "the network path between icscf and pyhss"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "from='scscf', to_ip='<pyhss_ip>'",
          "expected_if_hypothesis_holds": "High RTT or packet loss is observed. If the probe from icscf also shows issues, it points towards pyhss as the common point of failure.",
          "falsifying_observation": "Low RTT and zero packet loss are observed. This would suggest any issue seen from icscf is path-specific, not due to pyhss.",
          "conflates_with": []
        },
        {
          "tool": "get_network_status",
          "args_hint": "Check the running status of the pyhss container.",
          "expected_if_hypothesis_holds": "The pyhss container is in a 'down' or 'restarting' state.",
          "falsifying_observation": "The pyhss container is in a 'running' state.",
          "conflates_with": []
        }
      ],
      "notes": "This plan investigates the HSS hypothesis. It uses a pair of `measure_rtt` probes from two different clients (i-cscf, s-cscf) that both depend on the HSS. This allows for disambiguation between a network path issue and an issue with the HSS container itself. A third probe checks the basic status of the container. The plan avoids mechanism-scoping language as required by the feedback."
    }
  ]
}
